<script>
(()=> {
 const form=document.querySelector('.member-form');
 const fields=[...form.querySelectorAll('input[name],select[name],textarea[name]')];
 const messages={nama:{required:'Nama lengkap wajib diisi.',max:'Nama terlalu panjang. Maksimal 255 karakter.'},nik:{required:'NIK wajib diisi.',digits:'NIK harus terdiri dari tepat 16 angka.'},jenis_kelamin:{required:'Silakan pilih jenis kelamin.'},alamat:{required:'Alamat lengkap wajib diisi.',max:'Alamat terlalu panjang. Maksimal 1.000 karakter. Silakan ringkas alamat.'},dusun:{max:'Nama dusun terlalu panjang. Maksimal 255 karakter.'},desa:{required:'Nama desa wajib diisi.',max:'Nama desa terlalu panjang. Maksimal 255 karakter.'},no_hp:{required:'Nomor HP wajib diisi.',max:'Nomor HP terlalu panjang. Maksimal 30 karakter.'},pekerjaan:{max:'Nama pekerjaan terlalu panjang. Maksimal 255 karakter.'},foto:{}};
 function validateField(field){const key=field.name, value=field.value.trim(), rules=messages[key]||{};let msg='';if(field.required&&!value)msg=rules.required||'Kolom ini wajib diisi.';else if(key==='nik'&&value&&!/^\d{16}$/.test(value))msg=rules.digits;else if(field.maxLength>0&&value.length>field.maxLength)msg=rules.max||'Isian terlalu panjang.';const error=document.getElementById('error-'+key);if(error){error.textContent=msg;error.hidden=!msg;field.setAttribute('aria-invalid',msg?'true':'false');if(msg)field.setAttribute('aria-describedby',error.id);else field.removeAttribute('aria-describedby');}return !msg;}
 fields.forEach(field=>{field.addEventListener('input',()=>validateField(field));field.addEventListener('change',()=>validateField(field));});
 const fotoInput=document.getElementById('foto'), fotoPreview=document.getElementById('foto-preview');
 fotoInput?.addEventListener('change',()=>{const f=fotoInput.files?.[0],err=document.getElementById('error-foto');if(!f){fotoPreview.hidden=true;fotoPreview.removeAttribute('src');return;}let msg='';if(!['image/jpeg','image/png','image/webp'].includes(f.type))msg='Foto harus berformat JPG, PNG, atau WEBP.';else if(f.size>2*1024*1024)msg='Ukuran foto maksimal 2 MB.';if(err){err.textContent=msg;err.hidden=!msg;fotoInput.setAttribute('aria-invalid',msg?'true':'false');}if(msg){fotoInput.value='';fotoPreview.hidden=true;return;}fotoPreview.src=URL.createObjectURL(f);fotoPreview.hidden=false;});
 form.addEventListener('submit',event=>{let valid=true;fields.forEach(field=>{if(!validateField(field))valid=false;});if(!valid){event.preventDefault();const first=form.querySelector('[aria-invalid="true"]');if(first)first.focus();}});
 const card=document.getElementById('member-card'), nameInput=document.querySelector('[data-card-name]'), previewName=document.getElementById('preview-name'), toggle=document.getElementById('tilt-toggle'), flip=document.getElementById('flip-preview'), download=document.getElementById('download-preview');
 let tilt=true;
 flip.addEventListener('click',()=>card.classList.toggle('is-flipped'));
 const updateName=()=>previewName.textContent=(nameInput.value.trim()||'NAMA ANGGOTA').toLocaleUpperCase('id-ID');
 nameInput.addEventListener('input',updateName); updateName();
 card.addEventListener('pointermove',e=>{if(!tilt)return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;card.style.setProperty('--ry',((x-.5)*22)+'deg');card.style.setProperty('--rx',((.5-y)*18)+'deg');card.style.setProperty('--shine',(x*100-50)+'%')});
 card.addEventListener('pointerleave',()=>{card.style.setProperty('--rx','0deg');card.style.setProperty('--ry','0deg');card.style.setProperty('--shine','-40%')});
 toggle.addEventListener('click',()=>{tilt=!tilt;toggle.textContent='Efek 3D: '+(tilt?'aktif':'nonaktif');if(!tilt){card.style.setProperty('--rx','0deg');card.style.setProperty('--ry','0deg')}});
 download.addEventListener('click',()=>{const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=757;const c=canvas.getContext('2d');const g=c.createLinearGradient(0,0,1200,757);g.addColorStop(0,'#073e2a');g.addColorStop(.5,'#087443');g.addColorStop(1,'#123d2e');c.fillStyle=g;c.fillRect(0,0,1200,757);c.strokeStyle='#d8f7bd';c.lineWidth=3;c.strokeRect(22,22,1156,713);c.fillStyle='#e9ffcc';c.beginPath();c.arc(105,105,42,0,Math.PI*2);c.fill();c.fillStyle='#073e2a';c.font='bold 30px Arial';c.textAlign='center';c.fillText('NU',105,115);c.textAlign='left';c.fillStyle='#fff';c.font='bold 30px Arial';c.fillText('MWC NU CIKAKAK',170,95);c.font='20px Arial';c.fillText('KARTU ANGGOTA DIGITAL · PREVIEW',170,132);c.fillStyle='#f2dca1';c.roundRect(72,205,115,80,12);c.fill();c.fillStyle='#fff';c.font='bold 42px Arial';c.fillText((previewName.textContent||'NAMA ANGGOTA').slice(0,32),72,385);c.font='bold 22px Arial';c.fillText('KODE KARTU AKAN DIBUAT SETELAH DAFTAR',72,455);c.font='18px Arial';c.fillText('CIKAKAK · WANGON · BANYUMAS',72,680);c.font='15px Arial';c.fillText('PREVIEW - BUKAN KARTU RESMI',72,715);const a=document.createElement('a');a.download='preview-kartu-anggota-mwc-nu.png';a.href=canvas.toDataURL('image/png');a.click()});
})();
</script>
